INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','easy','mcq','Which layer of the GI wall lies between the circular muscle layer and the mucosa?','["A. Submucosa", "B. Serosa", "C. Myenteric plexus", "D. Longitudinal muscle"]','A','The GI wall layers from outside inward: serosa, longitudinal muscle, circular muscle, submucosa, mucosa. The submucosa contains Meissner''s plexus, blood vessels, and lymphatics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','easy','mcq','Auerbach''s (myenteric) plexus is located between which two layers of the GI wall?','["A. Mucosa and submucosa", "B. Circular muscle and longitudinal muscle", "C. Submucosa and circular muscle", "D. Longitudinal muscle and serosa"]','B','Auerbach''s plexus lies between the circular and longitudinal smooth muscle layers and primarily controls GI motility. Meissner''s plexus lies within the submucosa and controls secretion and local blood flow.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','mcq','Which nerve plexus primarily controls local intestinal secretion and absorption rather than motility?','["A. Myenteric plexus", "B. Celiac plexus", "C. Submucosal (Meissner''s) plexus", "D. Hypogastric plexus"]','C','Meissner''s (submucosal) plexus controls local intestinal secretion, absorption, and submucosal muscle tone. Auerbach''s (myenteric) plexus, located between muscle layers, primarily controls motility.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','mcq','The celiac artery supplies blood to which segment of the GI tract?','["A. Descending colon to rectum", "B. Entire small intestine and proximal colon", "C. Distal ileum and colon", "D. Lower oesophagus, stomach, proximal duodenum, liver, pancreas, and spleen"]','D','The celiac trunk (T12 level) supplies foregut derivatives: lower oesophagus, stomach, first and second parts of duodenum, liver, gallbladder, spleen, and pancreas. The superior mesenteric artery supplies the midgut.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','mcq','Which artery supplies the descending colon, sigmoid colon, and upper rectum?','["A. Inferior mesenteric artery", "B. Superior mesenteric artery", "C. Celiac artery", "D. Internal iliac artery"]','A','The inferior mesenteric artery (IMA) supplies hindgut structures: the descending colon, sigmoid colon, and upper rectum. The SMA supplies midgut from distal duodenum to proximal two-thirds of transverse colon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','hard','mcq','Sympathetic fibres to the GI tract originate from which spinal cord segments?','["A. C3\u2013C5", "B. T5\u2013L2", "C. T1\u2013T4", "D. L4\u2013S3"]','B','Preganglionic sympathetic fibres to the GI tract originate from spinal cord segments T5–L2. They synapse in prevertebral ganglia (celiac, superior mesenteric, inferior mesenteric) and postganglionic fibres release norepinephrine, generally inhibiting GI activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','easy','mcq','Approximately what percentage of vagal nerve fibres are afferent (sensory)?','["A. 20%", "B. 40%", "C. 80%", "D. 60%"]','C','Approximately 80% of vagal nerve fibres are afferent, transmitting signals from the GI tract to the brain stem. Only 20% are efferent motor fibres, underlining the importance of sensory feedback in vagovagal reflex arcs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','medium','mcq','Which cells generate the slow-wave electrical pacemaker activity in GI smooth muscle?','["A. Interstitial cells of Cajal", "B. Goblet cells", "C. Enterochromaffin cells", "D. Parietal cells"]','A','Interstitial cells of Cajal (ICC) act as electrical pacemakers in GI smooth muscle, generating slow-wave potentials (3–12/min depending on location) through cyclic ion channel opening. When slow waves reach threshold (~-40 mV), spike potentials trigger muscle contraction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','hard','mcq','Sacral parasympathetic fibres (S2–S4) primarily supply which portion of the GI tract?','["A. Stomach and proximal duodenum", "B. Entire small intestine", "C. Oesophagus and pharynx", "D. Distal half of large intestine and anus"]','D','Sacral parasympathetics (S2–S4) via pelvic nerves supply the distal large intestine (descending colon, sigmoid, rectum) and anus, and are critical for the defecation reflex. The vagus (CN X) supplies the oesophagus to the proximal transverse colon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Tract Anatomy','hard','mcq','Which layer of the GI wall holds sutures best and provides the most structural integrity in bowel anastomosis?','["A. Mucosa", "B. Submucosa", "C. Muscularis propria", "D. Serosa"]','B','The submucosa is the strongest layer of the GI wall due to its dense collagen and elastin content. Surgically, sutures placed through the submucosa provide the most reliable hold, making it the key layer in bowel anastomosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','easy','mcq','Which salivary gland is the primary source of salivary amylase?','["A. Sublingual gland", "B. Minor buccal glands", "C. Parotid gland", "D. Submandibular gland"]','C','The parotid gland produces purely serous saliva rich in salivary amylase (ptyalin). The submandibular gland contributes the greatest total resting salivary volume. The sublingual gland produces mainly mucous secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','easy','mcq','Salivary amylase (ptyalin) hydrolyses starch into which products?','["A. Glucose and galactose", "B. Amino acids and peptides", "C. Fructose and sucrose", "D. Maltose and small glucose polymers"]','D','Salivary amylase cleaves starch into maltose (a disaccharide) and small glucose polymers (3–9 glucose units). It does not completely break down starch to glucose; pancreatic amylase continues the process in the duodenum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','mcq','During the pharyngeal stage of swallowing, which structure prevents food from entering the nasopharynx?','["A. Soft palate", "B. Epiglottis", "C. True vocal cords", "D. Superior pharyngeal constrictor"]','A','During the pharyngeal stage the soft palate elevates and pulls backward to seal the nasopharynx, preventing nasal regurgitation. The epiglottis closes over the larynx to prevent tracheal aspiration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','mcq','What is the normal resting pressure of the lower oesophageal sphincter (LOS)?','["A. 2\u20135 mmHg", "B. 35\u201350 mmHg", "C. 5\u201310 mmHg", "D. 15\u201325 mmHg"]','D','The LOS maintains resting pressure of 15–25 mmHg above gastric pressure, preventing gastro-oesophageal reflux. In GORD, LOS pressure is typically reduced to below 10 mmHg.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','mcq','Which neurotransmitters mediate transient lower oesophageal sphincter relaxation during normal swallowing?','["A. VIP and nitric oxide", "B. Acetylcholine and norepinephrine", "C. Substance P and histamine", "D. Dopamine and serotonin"]','A','Transient LOS relaxation is mediated by inhibitory neurotransmitters VIP and nitric oxide released from myenteric plexus neurons. This allows the food bolus to enter the stomach. Acetylcholine contracts the LOS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','easy','mcq','Which stage of swallowing is entirely voluntary?','["A. Pharyngeal stage", "B. Oral (buccal) stage", "C. Oesophageal stage", "D. All stages are reflex"]','B','The oral (buccal) stage is the only voluntary stage, involving tongue movement to propel the bolus to the posterior pharynx. The pharyngeal and oesophageal stages are involuntary reflex actions coordinated by the swallowing centre in the medulla.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','hard','mcq','Achalasia results from degeneration of which neural elements in the oesophagus?','["A. Cholinergic excitatory myenteric neurons", "B. Sympathetic noradrenergic neurons", "C. Inhibitory neurons releasing nitric oxide and VIP", "D. Vagal afferent sensory neurons"]','C','Achalasia results from degeneration of inhibitory neurons in the myenteric plexus that release nitric oxide and VIP, normally causing LOS relaxation. Loss of these neurons leads to failure of LOS relaxation and functional oesophageal obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','medium','mcq','Primary oesophageal peristalsis is triggered by:','["A. Oesophageal distension alone", "B. Gastric acid reflux", "C. Parasympathetic stimulation alone", "D. The act of swallowing"]','D','Primary peristalsis is initiated by the voluntary act of swallowing. Secondary peristalsis occurs in response to oesophageal distension without a new swallow, helping clear retained material.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','hard','mcq','Saliva contains which immunological component providing mucosal defense in the oral cavity?','["A. Secretory IgA", "B. IgG", "C. IgM", "D. IgE"]','A','Secretory IgA (sIgA) is the primary immunoglobulin in saliva. It binds pathogens and prevents mucosal adhesion. The secretory component (provided by epithelial cells) protects sIgA from proteolytic degradation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Salivary Glands & Oesophagus','hard','mcq','The upper oesophageal sphincter (UOS) is formed primarily by which muscle?','["A. Inferior pharyngeal constrictor", "B. Cricopharyngeus muscle", "C. Palatopharyngeus muscle", "D. Thyropharyngeus muscle"]','B','The UOS is formed primarily by the cricopharyngeus muscle, part of the inferior pharyngeal constrictor. It is skeletal muscle under somatic neural control. It maintains constant resting tone and relaxes during swallowing to allow the food bolus to enter the oesophagus.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 64'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','easy','mcq','Which gastric cell type secretes hydrochloric acid (HCl)?','["A. Chief cells", "B. Parietal (oxyntic) cells", "C. G cells", "D. Mucous neck cells"]','B','Parietal (oxyntic) cells in the gastric fundus and body secrete both HCl and intrinsic factor. HCl is produced by the H+/K+-ATPase proton pump. Chief cells secrete pepsinogen; G cells secrete gastrin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','easy','mcq','Which gastric cell type secretes pepsinogen?','["A. Chief (peptic) cells", "B. Parietal cells", "C. G cells", "D. D cells"]','A','Chief (peptic) cells, predominantly in the fundus, secrete pepsinogen, the inactive precursor of pepsin. Pepsinogen is activated to pepsin by HCl (pH < 2) and by autocatalytic pepsin activity at pH 1.8–3.5.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','mcq','Which ion pump on the apical surface of parietal cells is the primary mechanism for HCl secretion?','["A. Na+/K+-ATPase", "B. Ca2+-ATPase", "C. Cl-/HCO3- exchanger", "D. H+/K+-ATPase"]','D','The H+/K+-ATPase (proton pump) on the apical membrane of parietal cells actively secretes H+ in exchange for K+, creating the highly acidic gastric environment (pH 0.8–1.0). Proton pump inhibitors irreversibly block this enzyme.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','mcq','Gastrin is secreted by G cells in response to which stimuli?','["A. Somatostatin and secretin", "B. Protein digestion products, gastric distension, and vagal stimulation", "C. Acidic gastric pH and fat in the duodenum", "D. CCK and glucagon"]','B','Gastrin release from antral G cells is stimulated by protein digestion products (peptides, amino acids) in the stomach, gastric distension, and vagal stimulation via GRP. It is inhibited by low gastric pH (< 2) and somatostatin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','easy','mcq','Which gastric secretory phase is initiated by the sight, smell, or thought of food?','["A. Gastric phase", "B. Intestinal phase", "C. Enteric phase", "D. Cephalic phase"]','D','The cephalic phase begins before food enters the stomach, triggered by the sight, smell, taste, or thought of food via vagal stimulation. It accounts for approximately 20–30% of total gastric acid secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','mcq','Intrinsic factor secreted by parietal cells is essential for absorption of which vitamin?','["A. Vitamin B12", "B. Vitamin B6", "C. Vitamin C", "D. Folic acid"]','A','Intrinsic factor (IF), a glycoprotein secreted by gastric parietal cells, binds vitamin B12 in the stomach. The IF–B12 complex is absorbed in the terminal ileum via cubam receptors. Loss of parietal cells in autoimmune gastritis causes pernicious anaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','hard','mcq','Which hormone inhibits gastric acid secretion both directly on parietal cells and indirectly by inhibiting gastrin release?','["A. Motilin", "B. Somatostatin", "C. CCK", "D. GIP"]','B','Somatostatin from D cells of the gastric antrum and fundus directly inhibits parietal cells and suppresses gastrin release from G cells by paracrine action. Low gastric pH stimulates D cell somatostatin release, creating a negative feedback loop.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','medium','mcq','The intestinal phase of gastric secretion contributes approximately what percentage of total gastric acid output?','["A. 50\u201360%", "B. 20\u201330%", "C. 5\u201310%", "D. 70\u201380%"]','C','The intestinal phase accounts for only about 5–10% of total gastric acid secretion. The gastric phase (~60–70%) and cephalic phase (~20–30%) dominate.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','hard','mcq','Long-term proton pump inhibitor use most commonly leads to which physiological consequence?','["A. Hypergastrinaemia", "B. Elevated pepsinogen levels", "C. Reduced mucus secretion", "D. Increased intrinsic factor production"]','A','PPIs block H+/K+-ATPase, raising intragastric pH. Reduced acid removes the inhibitory pH signal for gastrin release, leading to hypergastrinaemia. Chronic hypergastrinaemia causes ECL cell hyperplasia and, rarely, gastric carcinoid tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gastric Secretion','hard','mcq','Which cell type mediates histamine-stimulated acid secretion as an intermediary between gastrin and parietal cells?','["A. D cells", "B. G cells", "C. Mucous neck cells", "D. Enterochromaffin-like (ECL) cells"]','D','ECL cells in the gastric fundus release histamine in response to gastrin and vagal stimulation. Histamine acts on H2 receptors on parietal cells to stimulate HCl secretion via cAMP. H2-receptor antagonists (ranitidine, famotidine) block this pathway.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','easy','mcq','Which hormone is the primary stimulus for pancreatic enzyme secretion from acinar cells?','["A. Secretin", "B. Motilin", "C. Cholecystokinin (CCK)", "D. Gastrin"]','C','CCK, released from I cells of the duodenum and jejunum in response to fats and proteins, is the primary stimulus for pancreatic acinar cell enzyme secretion. Secretin primarily stimulates ductal cells to secrete bicarbonate-rich fluid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','easy','mcq','Which hormone stimulates pancreatic ductal cells to secrete bicarbonate-rich fluid?','["A. Secretin", "B. CCK", "C. Gastrin", "D. GIP"]','A','Secretin is released from S cells of the duodenum in response to acid (low pH chyme). It acts on pancreatic ductal cells to produce a high-volume, bicarbonate-rich secretion that neutralises gastric acid in the duodenum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','mcq','The two primary bile acids synthesised de novo in the liver are:','["A. Ursodeoxycholic acid and glycocholic acid", "B. Cholic acid and chenodeoxycholic acid", "C. Deoxycholic acid and lithocholic acid", "D. Taurocholic acid and glycochenodeoxycholic acid"]','B','Cholic acid and chenodeoxycholic acid are the primary bile acids synthesised from cholesterol in the liver. Gut bacteria 7alpha-dehydroxylate these to form deoxycholic acid and lithocholic acid (secondary bile acids), respectively.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','mcq','By approximately how many fold does the gallbladder concentrate bile?','["A. 50\u2013100 fold", "B. 2\u20133 fold", "C. 15\u201320 fold", "D. 5\u201310 fold"]','C','The gallbladder concentrates bile 5–20 fold by actively absorbing water and electrolytes while retaining bile salts, bilirubin, cholesterol, and lecithin, increasing the detergent effectiveness of bile.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','mcq','Pancreatic lipase requires which cofactor to function optimally on fat droplets in the presence of bile salts?','["A. Colipase", "B. Trypsinogen", "C. Phospholipase A2", "D. Bile salts"]','A','Colipase (secreted as pro-colipase by acinar cells, activated by trypsin) anchors pancreatic lipase to the lipid-water interface and displaces inhibitory bile salts from the fat droplet surface, allowing lipase to hydrolyse triglycerides.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','easy','mcq','Which cells of the exocrine pancreas secrete digestive enzymes?','["A. Islet beta-cells", "B. Acinar cells", "C. Centroacinar cells", "D. Ductal cells"]','B','Pancreatic acinar cells synthesise and secrete digestive enzymes: proteases (trypsinogen, chymotrypsinogen, proelastase), lipases, amylase, and nucleases. Ductal cells secrete bicarbonate-rich fluid. Islet cells have endocrine function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','hard','mcq','Enterokinase (enteropeptidase) activates which pancreatic proenzyme to initiate the proteolytic cascade?','["A. Chymotrypsinogen", "B. Proelastase", "C. Procarboxypeptidase", "D. Trypsinogen"]','D','Enterokinase cleaves the activation peptide from trypsinogen to form active trypsin. Trypsin then autocatalytically activates more trypsinogen and all other pancreatic proenzymes: chymotrypsinogen, proelastase, and procarboxypeptidase.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','hard','mcq','Where are bile salts actively reabsorbed to complete enterohepatic circulation?','["A. Duodenum", "B. Ascending colon", "C. Terminal ileum", "D. Proximal jejunum"]','C','Approximately 95% of bile salts are actively reabsorbed in the terminal ileum via the apical sodium-dependent bile acid transporter (ASBT). They enter the portal circulation and are recycled to the liver, cycling 6–8 times per day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','medium','mcq','Which component of bile functions as the primary emulsifier to facilitate fat digestion?','["A. Bilirubin", "B. Bile salts (bile acids)", "C. Cholesterol", "D. Phosphatidylserine"]','B','Bile salts are amphipathic molecules that emulsify large fat globules into small droplets, vastly increasing the surface area for pancreatic lipase action. They also form mixed micelles to solubilise fat digestion products for absorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Pancreatic & Biliary Secretion','hard','mcq','Secretin release from duodenal S cells is most potently triggered by which intraluminal stimulus?','["A. Glucose", "B. Long-chain fatty acids", "C. Amino acids", "D. Acid (pH < 4.5)"]','D','Secretin is released when duodenal luminal pH falls below 4.5 due to gastric acid entering the duodenum. It stimulates pancreatic and biliary bicarbonate secretion to neutralise the acid. Fat also stimulates secretin release, but acid is the most potent physiological trigger.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','easy','mcq','Which transporter absorbs glucose and galactose across the enterocyte apical membrane?','["A. SGLT1", "B. GLUT2", "C. GLUT5", "D. SGLT2"]','A','SGLT1 co-transports glucose and galactose with Na+ across the apical (brush border) membrane of enterocytes by secondary active transport. GLUT5 transports fructose by facilitated diffusion. GLUT2 on the basolateral membrane exports glucose to the bloodstream.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','easy','mcq','Fructose is absorbed across the enterocyte apical membrane by which transporter?','["A. SGLT2", "B. GLUT5", "C. SGLT1", "D. GLUT4"]','B','Fructose is absorbed from the gut lumen into enterocytes via GLUT5 (facilitated diffusion), independent of sodium. It exits the basolateral membrane via GLUT2 along with glucose and galactose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','mcq','Dietary fat is absorbed into intestinal lymphatics as which lipoprotein particle?','["A. VLDL", "B. LDL", "C. Chylomicrons", "D. HDL"]','C','Long-chain fatty acids and monoglycerides are re-esterified to triglycerides within enterocytes, packaged with apoB-48 and phospholipids into chylomicrons, and secreted into intestinal lacteals. Chylomicrons enter the bloodstream via the thoracic duct, bypassing portal circulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','mcq','Vitamin B12 absorption in the terminal ileum requires which receptor?','["A. Cubam (cubilin-amnionless complex)", "B. ASBT", "C. DMT1", "D. Megalin"]','A','The intrinsic factor-B12 complex is recognised by the cubam receptor (cubilin-amnionless complex) on terminal ileal enterocytes and internalised by receptor-mediated endocytosis. Absence of intrinsic factor (pernicious anaemia) or terminal ileal disease (Crohn''s) causes B12 deficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','easy','mcq','Where is dietary iron primarily absorbed in the GI tract?','["A. Ascending colon", "B. Duodenum and proximal jejunum", "C. Stomach", "D. Terminal ileum"]','B','Iron is primarily absorbed in the duodenum and proximal jejunum. Ferrous iron (Fe2+) is more efficiently absorbed than ferric iron (Fe3+). Vitamin C (ascorbic acid) reduces Fe3+ to Fe2+, enhancing absorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','mcq','Which brush border enzyme cleaves maltose into two glucose molecules?','["A. Sucrase", "B. Isomaltase", "C. Lactase", "D. Maltase"]','D','Maltase on the brush border of small intestinal enterocytes hydrolyses maltose (glucose-glucose, alpha-1,4 bond) into two glucose molecules. Sucrase cleaves sucrose into glucose and fructose; lactase cleaves lactose into glucose and galactose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','hard','mcq','Short-chain fatty acids produced by colonic bacterial fermentation are absorbed primarily by:','["A. Passive non-ionic diffusion and MCT1 transporter", "B. Active transport via SGLT1", "C. Chylomicron formation", "D. Receptor-mediated endocytosis"]','A','SCFAs (acetate, propionate, butyrate) are absorbed by passive non-ionic diffusion and the monocarboxylate transporter MCT1 on colonocyte apical membranes. Butyrate is the primary energy source for colonocytes and has anti-inflammatory and anti-neoplastic properties.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','hard','mcq','Fat-soluble vitamins (A, D, E, K) require which component for intestinal absorption?','["A. Intrinsic factor", "B. Cubam receptor", "C. Bile salt mixed micelles", "D. SGLT1 co-transporter"]','C','Fat-soluble vitamins A, D, E, and K are incorporated into bile salt mixed micelles along with fatty acids, monoglycerides, and lysophospholipids. Micelles facilitate their diffusion through the unstirred water layer to the enterocyte surface where passive diffusion occurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','medium','mcq','Which part of the small intestine is the primary site of carbohydrate and protein absorption?','["A. Ileocaecal junction", "B. Terminal ileum", "C. Duodenum", "D. Proximal jejunum"]','D','The proximal jejunum is the primary site of carbohydrate and protein absorption due to its large surface area (villi, microvilli) and high density of digestive enzymes and transporters. The ileum specifically absorbs bile salts and vitamin B12.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Intestinal Digestion & Absorption','hard','mcq','Calcium absorption in the duodenum is upregulated by which active vitamin D metabolite?','["A. 1,25-dihydroxyvitamin D (calcitriol)", "B. Vitamin D2 (ergocalciferol)", "C. 25-hydroxyvitamin D", "D. 24,25-dihydroxyvitamin D"]','A','1,25-dihydroxyvitamin D (calcitriol), produced by 1alpha-hydroxylation in the kidney stimulated by PTH, upregulates calbindin-D9k and TRPV6 channels in duodenal enterocytes, markedly increasing active calcium absorption.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','easy','mcq','What is the approximate cycle length of the migrating motor complex (MMC) during fasting?','["A. 30 minutes", "B. 90 minutes", "C. 120 minutes", "D. 60 minutes"]','B','The MMC cycles approximately every 90 minutes during fasting, sweeping undigested material and bacteria from the stomach and small intestine toward the colon (the ''intestinal housekeeper''). Motilin initiates MMC phase III and is abolished after a meal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','easy','mcq','Which cells are the primary pacemakers of GI slow-wave electrical activity?','["A. Smooth muscle cells of the muscularis mucosae", "B. Enterochromaffin cells", "C. Interstitial cells of Cajal (ICC)", "D. Myenteric neurons"]','C','Interstitial cells of Cajal (ICC) generate slow-wave pacemaker potentials setting the maximum frequency of GI contractions: approximately 3/min in the stomach, 12/min in the duodenum, and 8–9/min in the ileum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','mcq','Haustral contractions in the colon are best described as:','["A. Retrograde contractions preventing faecal entry into the ileum", "B. Mass movements occurring 3\u20134 times daily", "C. Propulsive waves sweeping the full colon length", "D. Segmental non-propulsive contractions that mix colonic contents"]','D','Haustral (segmenting) contractions are non-propulsive mixing movements that slowly turn and roll faecal content, facilitating water and electrolyte absorption. Mass movements (high-amplitude propagating contractions) propel content over large distances 3–4 times daily.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','mcq','The defecation reflex is primarily coordinated by:','["A. Sacral parasympathetic reflexes (S2\u2013S4) and the enteric nervous system", "B. Somatic motor neurons from L1\u2013L2", "C. Vagal afferents to the medullary vomiting centre", "D. Sympathetic fibres from T5\u2013L2"]','A','The defecation reflex involves intrinsic enteric reflexes and extrinsic sacral parasympathetic reflexes (S2–S4 via pelvic nerves). Rectal distension triggers reflex relaxation of the internal anal sphincter (involuntary) and voluntary relaxation of the external anal sphincter (pudendal nerve).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','mcq','Gastric emptying is most significantly inhibited by which duodenal stimuli?','["A. Alkaline chyme", "B. Fat and hyperosmolar solutions", "C. Distilled water", "D. Amino acids alone"]','B','Fat is the most potent inhibitor of gastric emptying, acting via CCK release and the enterogastric reflex. Hyperosmolar solutions and acid (pH < 3.5) also inhibit emptying, protecting the duodenum from overwhelming its buffering and absorptive capacity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','easy','mcq','Which hormone initiates phase III of the migrating motor complex during fasting?','["A. Secretin", "B. Gastrin", "C. Motilin", "D. CCK"]','C','Motilin, released from M cells of the duodenum and jejunum during fasting, initiates the strong phase III (activity front) of the MMC approximately every 90 minutes. Erythromycin is a motilin receptor agonist used as a prokinetic in gastroparesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','hard','mcq','Distension of the caecum reflexively affects the ileocaecal valve by:','["A. Stimulating motilin release", "B. Relaxing the ileocaecal sphincter to increase flow", "C. Activating vagal efferents to the small intestine", "D. Increasing ileocaecal sphincter tone to prevent backflow"]','D','Distension of the caecum or colon reflexively increases ileocaecal sphincter tone (colonoileal reflex), preventing backflow of bacteria-laden colonic contents into the sterile ileum. Ileal distension and gastrin relax the ileocaecal valve.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','hard','mcq','Mass movements in the colon occur most frequently in response to:','["A. MMC phase III propagation", "B. Motilin peaks during fasting", "C. Gastrocolic and duodenocolic reflexes after meals", "D. Rectal distension alone"]','C','Mass movements are most strongly triggered by the gastrocolic reflex (gastric distension) and duodenocolic reflex after meals, explaining the urge to defecate after eating. They sweep content from the transverse colon to the rectum 3–4 times daily.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','hard','mcq','The ''law of the intestine'' describes which pattern of activity during peristalsis?','["A. Relaxation above and below the bolus simultaneously", "B. Contraction oral to the bolus and relaxation caudal to it", "C. Contraction caudal to the bolus and relaxation oral to it", "D. Equal contraction above and below the bolus"]','B','The law of the intestine (Bayliss and Starling) states that intestinal distension causes excitation (contraction) orad and inhibition (relaxation) aborad, propelling content forward. Ascending excitation uses acetylcholine; descending inhibition uses VIP and nitric oxide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','GI Motility','medium','mcq','Which type of colonic contraction is primarily responsible for water absorption rather than propulsion?','["A. Haustral (segmenting) contractions", "B. Peristaltic waves", "C. Mass movements", "D. MMC phase III"]','A','Haustral contractions are stationary segmenting contractions that mix and churn colonic content, maximising contact time with the mucosa for water and electrolyte absorption. The colon can absorb up to 5–6 L/day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 63'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','easy','mcq','Gastrin is secreted by which cell type and from which GI location?','["A. I cells of the jejunum", "B. S cells of the duodenum", "C. K cells of the duodenum", "D. G cells of the gastric antrum"]','D','Gastrin is secreted by G cells primarily in the gastric antrum. Its main action is to stimulate gastric acid secretion from parietal cells (via ECL cell histamine release) and promote gastric mucosal growth.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','easy','mcq','CCK is released from which intestinal cell type in response to fat and protein?','["A. I cells", "B. S cells", "C. K cells", "D. G cells"]','A','CCK is released from I cells of the duodenum and proximal jejunum in response to fat and protein. CCK stimulates pancreatic enzyme secretion, gallbladder contraction, sphincter of Oddi relaxation, and inhibits gastric emptying.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','mcq','Glucose-dependent insulinotropic peptide (GIP) is released from which intestinal cells?','["A. S cells", "B. L cells", "C. K cells", "D. I cells"]','C','GIP is released from K cells of the duodenum and jejunum in response to glucose and fat. Its primary physiological role is to potentiate glucose-stimulated insulin secretion from pancreatic beta-cells (the incretin effect).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','mcq','Secretin is released from S cells in response to acid and primarily stimulates:','["A. Gallbladder contraction", "B. Small intestinal crypt fluid secretion", "C. Liver bile production", "D. Pancreatic bicarbonate secretion"]','D','Secretin primarily stimulates pancreatic ductal cells to secrete large volumes of bicarbonate-rich fluid, neutralising acid chyme in the duodenum. It also stimulates biliary bicarbonate secretion and inhibits gastrin release.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','mcq','GLP-1 is released from which intestinal cells and has which principal metabolic effect?','["A. L cells; stimulates glucose-dependent insulin release and inhibits glucagon", "B. K cells; inhibits insulin release", "C. I cells; stimulates pancreatic enzyme release", "D. G cells; stimulates gastric acid secretion"]','A','GLP-1 is released from L cells of the distal ileum and colon in response to luminal nutrients. It stimulates insulin secretion in a glucose-dependent manner, inhibits glucagon, slows gastric emptying (ileal brake), and reduces appetite. GLP-1 receptor agonists are used in T2DM therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','hard','mcq','Which gut hormone initiates MMC phase III and is mimicked by erythromycin?','["A. CCK", "B. Motilin", "C. Neurotensin", "D. Secretin"]','B','Motilin, released from M cells of the duodenum and jejunum during fasting, initiates the high-amplitude phase III MMC contractions approximately every 90 minutes. Erythromycin and its derivatives are motilin receptor agonists used as prokinetics in gastroparesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','hard','mcq','Somatostatin inhibits GI secretion via which receptor types?','["A. Muscarinic M3 receptor", "B. Toll-like receptor 4", "C. SSTR2 and SSTR5 (Gi-coupled receptors)", "D. SSTR1 (Gs-coupled receptor)"]','C','Somatostatin acts via SSTR2 and SSTR5 (Gi-coupled receptors), reducing cAMP and suppressing secretory activity. This underlies the mechanism of somatostatin analogues (octreotide, lanreotide) in treating carcinoid tumours, acromegaly, and GI fistulas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','easy','mcq','CCK causes gallbladder contraction and simultaneously causes which other action on the sphincter of Oddi?','["A. No effect", "B. Contraction", "C. Rhythmic oscillation", "D. Relaxation"]','D','CCK simultaneously contracts the gallbladder and relaxes the sphincter of Oddi, allowing concentrated bile to flow into the duodenum. This coordinated response maximises bile delivery to facilitate fat emulsification and absorption after a fat-containing meal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','hard','mcq','Peptide YY (PYY), released postprandially from L cells, produces which physiological effect?','["A. Increases gastric emptying rate", "B. Inhibits gastric acid and pancreatic secretion (ileal brake)", "C. Stimulates MMC phase III", "D. Stimulates appetite via the arcuate nucleus"]','B','PYY is released postprandially from L cells of the terminal ileum and colon. It contributes to the ileal brake: slowing gastric emptying, inhibiting pancreatic secretion, and reducing appetite via Y2 receptors in the hypothalamus. PYY levels are reduced in obesity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Hormones','medium','mcq','Which gut hormone, when abnormally elevated due to a gastrin-secreting tumour, causes Zollinger-Ellison syndrome?','["A. Gastrin", "B. Motilin", "C. CCK", "D. Secretin"]','A','Zollinger-Ellison syndrome is caused by a gastrinoma (gastrin-secreting tumour usually in the pancreas or duodenum) producing massive hypergastrinaemia, driving extreme gastric acid hypersecretion and multiple recurrent peptic ulcers. Serum gastrin > 1000 pg/mL strongly suggests this diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 65'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','easy','mcq','The approximate half-life of serum albumin is:','["A. 2\u20133 days", "B. 7\u201310 days", "C. 20 days", "D. 60 days"]','C','Albumin has a half-life of approximately 20 days. Because of this long half-life, serum albumin reflects chronic rather than acute liver synthetic function. Prealbumin (transthyretin, half-life ~2 days) is a more sensitive marker of acute nutritional or hepatic status.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','easy','mcq','Which coagulation factors require vitamin K for their synthesis in the liver?','["A. Factors I, V, VIII, XIII", "B. Factors XI, XII", "C. Von Willebrand factor and factor VIII", "D. Factors II, VII, IX, X"]','D','Coagulation factors II (prothrombin), VII, IX, and X are vitamin K-dependent, along with protein C and protein S. Vitamin K is required for gamma-carboxylation of glutamate residues, enabling calcium binding and activation. Warfarin inhibits vitamin K epoxide reductase.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','mcq','Which cytochrome P450 isoenzyme is most important for hepatic drug metabolism?','["A. CYP3A4", "B. CYP1A2", "C. CYP2D6", "D. CYP2C9"]','A','CYP3A4 is the most abundant hepatic cytochrome P450 isoenzyme, metabolising approximately 50% of all drugs. It is inducible (by rifampicin, carbamazepine, phenytoin) and inhibited (by azole antifungals, macrolides, grapefruit juice).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','mcq','Unconjugated bilirubin is transported in blood bound to which protein?','["A. Transferrin", "B. Albumin", "C. Haptoglobin", "D. Alpha-1-antitrypsin"]','B','Unconjugated (indirect) bilirubin is hydrophobic and transported in plasma tightly bound to albumin. It cannot be filtered by the kidney, hence no bilirubinuria in prehepatic jaundice. In the liver, it is conjugated with glucuronic acid by UGT1A1.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','mcq','Primary bile acids are converted to secondary bile acids by which process?','["A. Hepatic 7alpha-hydroxylation", "B. Renal 1alpha-hydroxylation", "C. Colonic bacterial 7alpha-dehydroxylation", "D. Pancreatic esterification"]','C','Gut bacteria in the colon perform 7alpha-dehydroxylation: cholic acid → deoxycholic acid, and chenodeoxycholic acid → lithocholic acid (secondary bile acids). Approximately 95% of bile acids are reabsorbed and recycled via enterohepatic circulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','mcq','The primary pathway for ammonia detoxification in the liver is:','["A. Urea cycle (ornithine cycle)", "B. Krebs cycle", "C. Beta-oxidation", "D. Glycogen synthesis"]','A','The urea cycle (ornithine cycle) in periportal hepatocytes converts ammonia to urea, excreted by the kidneys. In hepatic failure, impaired urea synthesis leads to hyperammonaemia and hepatic encephalopathy. Lactulose and rifaximin reduce colonic ammonia production.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','mcq','Which lipoprotein produced by the liver is the primary transporter of endogenous triglycerides to peripheral tissues?','["A. LDL", "B. HDL", "C. Chylomicrons", "D. VLDL"]','D','VLDL (very-low-density lipoprotein) is synthesised by the liver and contains apoB-100. It transports endogenous triglycerides from the liver to peripheral tissues. VLDL is progressively delipidated by lipoprotein lipase to form IDL, then LDL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','easy','mcq','Kupffer cells in the liver are classified as which cell type?','["A. Natural killer cells", "B. Resident macrophages", "C. Hepatic stellate cells (Ito cells)", "D. Endothelial cells"]','B','Kupffer cells are the liver''s resident macrophages lining hepatic sinusoids. They phagocytose bacteria, cellular debris, and foreign particles from the portal circulation, comprising approximately 80–90% of the body''s fixed macrophage population.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','hard','mcq','In obstructive jaundice, which laboratory finding distinguishes it from haemolytic (prehepatic) jaundice?','["A. Elevated reticulocyte count", "B. Elevated unconjugated bilirubin", "C. Bilirubinuria (conjugated bilirubin in urine)", "D. Absent urobilinogen in stool only"]','C','In obstructive jaundice, conjugated (direct, water-soluble) bilirubin accumulates in blood and is filtered by the kidney, causing dark urine (bilirubinuria) and absent urobilinogen. In haemolytic jaundice, unconjugated bilirubin predominates and there is no bilirubinuria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Liver Physiology','medium','mcq','Hepatic stellate cells (Ito cells) are responsible for which process in chronic liver injury?','["A. Bilirubin conjugation", "B. Gluconeogenesis", "C. Bile acid synthesis", "D. Collagen deposition and hepatic fibrosis"]','D','Hepatic stellate cells normally store vitamin A. In chronic liver injury, TGF-beta activates them to transdifferentiate into myofibroblasts that produce excess collagen (types I and III), leading to hepatic fibrosis and ultimately cirrhosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 70'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','easy','mcq','Which proteins form the paracellular tight junctions that regulate intestinal permeability?','["A. Fibronectin and laminin", "B. Claudins and occludin", "C. E-cadherin and beta-catenin", "D. Collagen IV and nidogen"]','B','Intestinal tight junctions (zonula occludens) are formed by transmembrane proteins claudins and occludin, scaffolded intracellularly by ZO-1, ZO-2, and ZO-3. Claudin-2 forms paracellular water channels; claudin-4/8 are barrier-forming. Dysregulation causes increased intestinal permeability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','easy','mcq','The dominant immunoglobulin secreted across the intestinal epithelium into the gut lumen is:','["A. IgE", "B. IgM", "C. Secretory IgA (sIgA)", "D. IgG"]','C','Secretory IgA (sIgA) is the predominant immunoglobulin at mucosal surfaces. Dimeric IgA produced by lamina propria plasma cells is transported across epithelial cells via the polymeric immunoglobulin receptor, gaining a secretory component that protects it from luminal proteolysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','mcq','Which intestinal cell type secretes mucin glycoproteins that form the protective mucus layer?','["A. Goblet cells", "B. Enterocytes", "C. Paneth cells", "D. Enteroendocrine cells"]','A','Goblet cells throughout the intestinal epithelium (most numerous in the colon) produce and secrete mucin glycoproteins (primarily MUC2 in the colon). The mucus gel layer provides a physical barrier against luminal microbes while allowing nutrient diffusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','mcq','Paneth cells contribute to mucosal immunity by secreting which antimicrobial substances?','["A. TNF-alpha and IL-6", "B. IgA and complement", "C. Histamine and serotonin", "D. Defensins and lysozyme"]','D','Paneth cells at the base of intestinal crypts (most numerous in ileum) secrete alpha-defensins (cryptdins), lysozyme, phospholipase A2, and RegIIIgamma. These antimicrobial peptides kill bacteria and maintain a bacteria-free zone at the crypt base where intestinal stem cells reside.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','mcq','The predominant bacterial phyla in the healthy adult human large intestine are:','["A. Spirochaetes and Fusobacteria", "B. Firmicutes and Bacteroidetes", "C. Proteobacteria and Actinobacteria", "D. Tenericutes and Verrucomicrobia"]','B','The healthy adult large intestine microbiome is dominated by Firmicutes (e.g., Lactobacillus, Clostridium, Ruminococcus) and Bacteroidetes (e.g., Bacteroides, Prevotella), comprising approximately 90% of gut flora. The Firmicutes:Bacteroidetes ratio is often altered in obesity and IBD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','hard','mcq','Butyrate produced by colonic bacteria has which primary effect on colonocytes?','["A. Serves as the primary energy substrate and promotes tight junction integrity", "B. Inhibits glycolysis", "C. Suppresses mucin secretion", "D. Stimulates apoptosis in normal epithelial cells"]','A','Butyrate, produced by bacterial fermentation of dietary fibre, is the primary energy source for colonocytes (contributing ~60–70% of their energy). It also upregulates tight junction proteins, has anti-inflammatory effects (inhibiting NF-kappaB), and may suppress colorectal cancer development.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','hard','mcq','Clostridium difficile causes colitis by producing which toxins?','["A. Cholera toxin and heat-labile toxin", "B. Staphylococcal enterotoxin B and TSST-1", "C. Enterotoxin A (TcdA) and cytotoxin B (TcdB)", "D. Shiga toxin and verotoxin"]','C','C. difficile produces toxin A (TcdA, enterotoxin) and toxin B (TcdB, cytotoxin), which glucosylate and inactivate Rho GTPases. This disrupts the actin cytoskeleton, destroys tight junctions, causes enterocyte apoptosis, and leads to pseudomembranous colitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','easy','mcq','Which specialised epithelial cells overlie Peyer''s patches and sample luminal antigens by transcytosis?','["A. Enterochromaffin cells", "B. Paneth cells", "C. Goblet cells", "D. M (microfold) cells"]','D','M (microfold) cells are specialised follicle-associated epithelial cells overlying Peyer''s patches. They endocytose and transcytose luminal antigens and microorganisms to underlying immune cells (dendritic cells, macrophages, B and T lymphocytes), initiating mucosal immune responses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','hard','mcq','Bacterial lipopolysaccharide (LPS) translocated across a leaky gut activates which innate immune receptor?','["A. NLRP3 inflammasome", "B. TLR4 (Toll-like receptor 4)", "C. NOD2", "D. TLR9"]','B','LPS (endotoxin) from gram-negative bacteria binds TLR4 on macrophages via CD14 and MD-2 co-receptors, activating NF-kappaB signalling and triggering TNF-alpha, IL-1beta, and IL-6 release, contributing to metabolic endotoxaemia in obesity and NASH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Gut Microbiome & Barrier Function','medium','mcq','Intestinal epithelial cells are replaced approximately every:','["A. 3\u20135 days", "B. 4\u20136 weeks", "C. 10\u201314 days", "D. 1\u20132 days"]','A','Intestinal epithelial cells turn over in approximately 3–5 days. Stem cells in the crypts of Lieberkühn continuously proliferate and differentiate into enterocytes, goblet cells, enteroendocrine cells, and Paneth cells, which migrate up the villus and are shed at the tip.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 66'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','easy','mcq','The vomiting (emetic) centre is located in which brain region?','["A. Hypothalamus", "B. Medulla oblongata", "C. Cerebral cortex", "D. Cerebellum"]','B','The vomiting centre is located in the lateral reticular formation of the medulla oblongata. It coordinates vomiting by receiving inputs from the chemoreceptor trigger zone (CTZ), vestibular apparatus, vagal afferents, and higher cortical centres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','easy','mcq','The chemoreceptor trigger zone (CTZ) lies in the floor of the fourth ventricle and has which unique anatomical feature?','["A. Within the blood-brain barrier", "B. Near the respiratory centre only", "C. Outside the blood-brain barrier", "D. Highly myelinated"]','C','The CTZ (area postrema) is outside the blood-brain barrier, allowing it to be activated by emetic chemicals in the blood (drugs, toxins, uraemic metabolites). Dopamine (D2), serotonin (5-HT3), and NK1 receptors in the CTZ are targets of antiemetic drugs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','mcq','Ghrelin is produced primarily from which location and has which effect on appetite?','["A. Gastric fundal oxyntic gland cells; stimulates appetite", "B. Pancreatic alpha-cells; inhibits glucagon", "C. Small intestine L cells; stimulates satiety", "D. Adipose tissue; suppresses appetite"]','A','Ghrelin is produced mainly by X/A-like cells of the gastric fundal oxyntic glands. It is the only known circulating orexigenic gut hormone. Levels rise before meals and fall after eating. Ghrelin acts on hypothalamic arcuate nucleus NPY/AgRP neurons to stimulate food intake.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','mcq','Leptin secreted by adipose tissue acts on the hypothalamus to:','["A. Stimulate the lateral hypothalamic area to increase hunger", "B. Stimulate NPY/AgRP neurons, increasing appetite", "C. Inhibit POMC/CART neurons, decreasing satiety", "D. Inhibit NPY/AgRP neurons and stimulate POMC/CART neurons, reducing food intake"]','D','Leptin acts on arcuate nucleus neurons to inhibit orexigenic NPY/AgRP neurons (reducing appetite) and stimulate anorexigenic POMC/CART neurons (increasing satiety). Leptin deficiency or resistance leads to hyperphagia and obesity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','mcq','The vagovagal reflex controlling gastric secretion and motility involves:','["A. Afferent vagal signals to the brain stem, then efferent vagal fibres back to GI tract", "B. Afferent signals from gut wall to spinal cord, then efferent sympathetic fibres", "C. Portal circulation to liver, then hepatic nerve fibres", "D. Enteric nervous system reflexes entirely within the gut wall"]','A','Vagovagal reflexes involve afferent vagal fibres (80% of vagal fibres are afferent) transmitting signals from GI mechanoreceptors and chemoreceptors to the nucleus tractus solitarius in the medulla. Efferent fibres return via the dorsal motor nucleus of the vagus to control secretion and motility.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','hard','mcq','During vomiting, which sequence of events precedes retching and gastric expulsion?','["A. Pylorus opens, cardia relaxes, diaphragm contracts", "B. Nausea, retrograde giant contraction of small intestine, LOS relaxation, then diaphragm and abdominal muscle contraction", "C. Glottis opens, soft palate descends, gastric relaxation", "D. Cardiac sphincter contracts, pylorus relaxes, retroperistalsis"]','B','The vomiting sequence: nausea and hypersalivation → retrograde giant contractions sweep small intestinal content into stomach → LOS relaxation → synchronous contraction of diaphragm, abdominal muscles with glottis closed and soft palate elevated → gastric expulsion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','hard','mcq','Destruction of the ventromedial hypothalamic (VMH) nucleus results in:','["A. Loss of the vomiting reflex", "B. Polydipsia and hyponatraemia", "C. Hyperphagia and obesity", "D. Anorexia and weight loss"]','C','Destruction of the VMH (the ''satiety centre'') causes voracious hyperphagia and morbid obesity in animals. The VMH normally inhibits the lateral hypothalamic area (the ''feeding centre''). This model established the dual-centre hypothesis of appetite control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','easy','mcq','The gastrocolic reflex refers to:','["A. Reflux of colonic bacteria into the terminal ileum", "B. Inhibition of gastric emptying by colonic contents", "C. Gastric acid secretion stimulated by colonic distension", "D. Increased colonic mass movements triggered by gastric or duodenal distension after a meal"]','D','The gastrocolic reflex is triggered when food enters the stomach and duodenum, stimulating mass movements in the colon. This explains the urge to defecate shortly after eating. It is mediated by neural pathways and hormones (CCK, gastrin) and is exaggerated in irritable bowel syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','hard','mcq','Which hypothalamic neuropeptide released from arcuate nucleus AgRP/NPY neurons is most potent in stimulating food intake?','["A. Alpha-MSH", "B. Neuropeptide Y (NPY)", "C. Oxytocin", "D. CART"]','B','NPY, co-released with AgRP from arcuate nucleus neurons, is one of the most potent orexigenic signals in the CNS. AgRP antagonises MC4R receptors to further promote appetite. Ghrelin activates NPY/AgRP neurons. Alpha-MSH (from POMC neurons) and CART are anorexigenic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72'),
('{"medicine"}','Medicine','Gastroenterology','Anatomy & Physiology','Regulation of Appetite & GI Reflexes','medium','mcq','The enterogastric reflex inhibits gastric acid secretion and motility when which conditions are detected in the duodenum?','["A. High pH (alkaline chyme)", "B. Mechanical distension with water only", "C. Presence of fat, acid (low pH), and hyperosmolality", "D. Amino acids and glucose only"]','C','The enterogastric reflex inhibits gastric secretion and emptying when the duodenum detects fat, acid (pH < 3.5), and hyperosmolality in arriving chyme. This prevents overwhelming the duodenum''s buffering and absorptive capacity and is mediated by enteric reflexes and hormones (secretin, CCK, GIP).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Guyton & Hall Medical Physiology 14th Ed, Chapter 72');
